add('simplifier', 'SpecHygiene', f"""Validate this wave's spec hygiene. Read {L}/.ufo/waves/round-30/make-spec-w1.py (generator; read-only) and the rendered plan {L}/.ufo/waves/round-30/w1-dispatch.json if present. Check: distinct item ids and prompts; roles only from scout, reviewer, critic, connector, sentinel, executor, mutation-tester, revenger, simplifier, scribe; flash roles (executor, scribe, critic, sentinel, revenger, simplifier) >= 50 % and attack roles (reviewer, critic, mutation-tester) >= 25 % of seats; every path absolute; no item asks a seat to write outside {W}/ or its scratch; every scratch path under {SCR}/; no two items deliver the same file. Report defects with item ids.""")

c = collections.Counter(i['role'] for i in ITEMS)
n = len(ITEMS)
assert len({i['item'] for i in ITEMS}) == n and len({i['prompt'] for i in ITEMS}) == n
flash = sum(c[r] for r in ('executor', 'scribe', 'critic', 'sentinel', 'revenger', 'simplifier'))
attack = sum(c[r] for r in ('reviewer', 'critic', 'mutation-tester'))
assert 32 <= n <= 64 and flash * 2 >= n and attack * 4 >= n, (n, flash, attack)
spec = {'wave': 'souji-r30-w1', 'reportDir': '.ufo/waves/round-30/w1', 'maxLanes': 64, 'context': CONTEXT, 'items': ITEMS}
json.dump(spec, open(L + '/.ufo/waves/round-30/w1-spec.json', 'w'), ensure_ascii=False, indent=1)
print(n, dict(c), 'flash', flash, 'attack', attack)
